ALTER TABLE core.opportunities DISABLE TRIGGER opportunities_state_gate;
ALTER TABLE core.tnas DISABLE TRIGGER tnas_state_gate;
ALTER TABLE core.proposals DISABLE TRIGGER proposals_state_gate;
ALTER TABLE core.quotations DISABLE TRIGGER quotations_state_gate;
ALTER TABLE core.quotations DISABLE TRIGGER trg_quotations_freeze_applied;

