SET CONSTRAINTS core.trg_quotation_reconciled, core.trg_quotation_floor, core.trg_invoice_reconciled, core.trg_credit_note_within_invoice IMMEDIATE;
SET CONSTRAINTS core.trg_quotation_reconciled, core.trg_quotation_floor, core.trg_invoice_reconciled, core.trg_credit_note_within_invoice DEFERRED;

